package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;
public final class ConversationUpgradeChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("conversation upgrade "+n);}interface Action{void run()throws Exception;}static void rejects(Action a)throws Exception{try{a.run();throw new AssertionError("expected refusal");}catch(IOException|IllegalArgumentException expected){n++;}}
 static JSONObject row(String id,String message)throws Exception{return new JSONObject().put("key",id).put("message",message).put("tracked",true).put("accepted",true).put("requestState","QUEUED").put("time",1);}
 static void setup(Context c,JSONObject...rows)throws Exception{JSONArray list=new JSONArray();java.lang.reflect.Field pending=MainActivity.class.getDeclaredField("pendingCommand");pending.setAccessible(true);pending.set(null,"");c.getSharedPreferences("phone_secretary",0).edit().clear().commit();for(JSONObject row:rows){list.put(row);ok(MainActivity.queueTrackedWebCommand(c,row.getString("key"),row.getString("message")));}c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",list.toString()).commit();}
 static JSONArray ledger(Context c)throws Exception{return new JSONArray(c.getSharedPreferences("loki_web_console",0).getString("outbox","[]"));}
 static JSONObject change(String key,String action,String op)throws Exception{return new JSONObject().put("key",key).put("action",action).put("changeId",op);}
 public static int run(Context base,String path)throws Exception{File root=new File(path);root.mkdirs();Context c=new ContextWrapper(base){public File getFilesDir(){return root;}public Context getApplicationContext(){return this;}};
 String a="a".repeat(64),b="b".repeat(64);setup(c,row(a,"first"),row(b,"second"));ok(MainActivity.queuedWebOrder(c).getJSONObject(1).getInt("position")==2);
 JSONObject cancel=change(a,"cancel","cancel-001");ok(QueuedConversation.change(c,cancel).getBoolean("cancelled"));ok(!MainActivity.hasQueuedWebCommand(c,a));ok(MainActivity.hasQueuedWebCommand(c,b));ok(ledger(c).getJSONObject(0).getString("requestState").equals("CANCELLED"));ok(QueuedConversation.change(c,cancel).getBoolean("duplicate"));
 JSONObject late=LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",a).put("event","RECEIVED"));ok(!late.getBoolean("execute"));ok(late.getString("requestState").equals("CANCELLED"));late=LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",a).put("event","RUNNING"));ok(!late.getBoolean("execute"));ok(MainActivity.hasQueuedWebCommand(c,b));
 setup(c,row(a,"old"),row(b,"later"));JSONObject edit=change(a,"edit","edit-0001").put("message","corrected");JSONObject changed=QueuedConversation.change(c,edit);String key=changed.getString("requestKey");ok(!key.equals(a));ok(MainActivity.queuedWebOrder(c).getJSONObject(0).getString("id").equals(key));ok(MainActivity.queuedWebOrder(c).getJSONObject(1).getString("id").equals(b));ok(ledger(c).getJSONObject(0).getString("requestState").equals("SUPERSEDED"));ok(ledger(c).getJSONObject(2).getString("message").equals("corrected"));ok(ConversationRecoveryStore.read(c,key).getJSONObject("payload").getString("message").equals("corrected"));ok(QueuedConversation.change(c,edit).getBoolean("duplicate"));ok(MainActivity.queuedWebOrder(c).length()==2);rejects(()->QueuedConversation.change(c,new JSONObject(edit.toString()).put("message","different")));
 ok(!LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",a).put("event","RECEIVED")).getBoolean("execute"));ok(MainActivity.hasQueuedWebCommand(c,key));ok(!LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",a).put("event","RUNNING")).getBoolean("execute"));ok(ledger(c).getJSONObject(0).getString("requestState").equals("SUPERSEDED"));
 LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",key).put("event","RECEIVED"));rejects(()->QueuedConversation.change(c,change(key,"cancel","cancel-002")));rejects(()->QueuedConversation.change(c,change(key,"edit","edit-0002").put("message","too late")));ok(LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",key).put("event","RUNNING")).getBoolean("execute"));ok(!LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",key).put("event","RUNNING")).getBoolean("execute"));
 LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",key).put("event","ANSWERED"));JSONObject finished=ledger(c).getJSONObject(2);ok(finished.getLong("receivedAt")>0);ok(finished.getLong("startedAt")>=finished.getLong("receivedAt"));ok(finished.getLong("finishedAt")>=finished.getLong("startedAt"));rejects(()->QueuedConversation.change(c,change(key,"cancel","cancel-003")));
 rejects(()->QueuedConversation.change(c,change("bad","cancel","cancel-003")));rejects(()->QueuedConversation.change(c,change(b,"unknown","cancel-003")));rejects(()->QueuedConversation.change(c,change(b,"edit","edit-0003").put("message","__LOKI_UNSAFE__")));ok(MainActivity.hasQueuedWebCommand(c,b));
 ok(com.example.rokidkeyboardbridge.ConversationPacingPolicy.INTERVAL_MS==10000);ok(com.example.rokidkeyboardbridge.ConversationPacingPolicy.successAt(1000,500)==10500);ok(com.example.rokidkeyboardbridge.ConversationPacingPolicy.successAt(20000,500)==20000);
 for(int attempt=0;attempt<8;attempt++){setup(c,row(a,"race first"),row(b,"race second"));final String operation="race-cancel-"+attempt;java.util.concurrent.CountDownLatch start=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{java.util.concurrent.Future<?> cancelRace=pool.submit(()->{try{start.await();QueuedConversation.change(c,change(a,"cancel",operation));}catch(IOException expected){}catch(Exception error){throw new RuntimeException(error);}});java.util.concurrent.Future<?> receiveRace=pool.submit(()->{try{start.await();LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",a).put("event","RECEIVED"));}catch(Exception error){throw new RuntimeException(error);}});start.countDown();cancelRace.get(10,java.util.concurrent.TimeUnit.SECONDS);receiveRace.get(10,java.util.concurrent.TimeUnit.SECONDS);String state=ledger(c).getJSONObject(0).getString("requestState");ok(state.equals("CANCELLED")||state.equals("RECEIVED"));JSONObject permission=LokiWebConsole.trackedReceipt(c,new JSONObject().put("id",a).put("event","RUNNING"));ok(permission.getBoolean("execute")==state.equals("RECEIVED"));ok(MainActivity.hasQueuedWebCommand(c,b));}finally{pool.shutdownNow();}}
 java.lang.reflect.Method post=MainActivity.class.getDeclaredMethod("buildPostLogResult",String.class);post.setAccessible(true);MainActivity owner=ReliabilityChecks.owner(c);post.invoke(owner,new JSONObject().put("kind","ユーザー").put("message","paired fixture").put("requestId",b).toString());post.invoke(owner,new JSONObject().put("kind","Gemini").put("message","paired reply").put("requestId",b).toString());JSONArray history=owner.webHistory();ok(history.getJSONObject(history.length()-2).getString("requestId").equals(b));ok(history.getJSONObject(history.length()-1).getString("requestId").equals(b));post.invoke(owner,new JSONObject().put("kind","Gemini").put("message","legacy reply").put("requestId","bad").toString());history=owner.webHistory();ok(!history.getJSONObject(history.length()-1).has("requestId"));
 c.getSharedPreferences("loki_web_console",0).edit().remove("outbox").commit();c.getSharedPreferences("phone_secretary",0).edit().clear().commit();return n;
 }
}
